CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS families(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parents(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, username TEXT NOT NULL COLLATE NOCASE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(family_id,username));
CREATE TABLE IF NOT EXISTS children(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, name TEXT NOT NULL, avatar TEXT NOT NULL, color TEXT NOT NULL, level INTEGER NOT NULL DEFAULT 1, experience REAL NOT NULL DEFAULT 0, points_balance INTEGER NOT NULL DEFAULT 0 CHECK(points_balance>=0), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, actor_type TEXT NOT NULL CHECK(actor_type IN ('parent','child')), actor_id TEXT NOT NULL, selected_child_id TEXT REFERENCES children(id) ON DELETE SET NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_templates(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, points INTEGER NOT NULL CHECK(points>0), repeat_rule TEXT NOT NULL CHECK(repeat_rule IN ('once','daily','weekly')), repeat_weekday INTEGER NOT NULL DEFAULT 1 CHECK (repeat_weekday BETWEEN 0 AND 6), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_instances(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, template_id TEXT REFERENCES task_templates(id) ON DELETE SET NULL, child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE, period_key TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, points INTEGER NOT NULL, repeat_rule TEXT NOT NULL, repeat_weekday INTEGER NOT NULL DEFAULT 1 CHECK (repeat_weekday BETWEEN 0 AND 6), due_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('todo','pending_review','completed','rejected')), created_at TEXT NOT NULL, UNIQUE(template_id,period_key));
CREATE TABLE IF NOT EXISTS task_submissions(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, task_instance_id TEXT NOT NULL REFERENCES task_instances(id) ON DELETE CASCADE, child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE, note TEXT NOT NULL, submitted_at TEXT NOT NULL, reviewed_at TEXT, review_note TEXT, approved INTEGER);
CREATE TABLE IF NOT EXISTS wishes(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, points_cost INTEGER NOT NULL CHECK(points_cost>0), icon TEXT NOT NULL, color TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS redemptions(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, wish_id TEXT REFERENCES wishes(id) ON DELETE SET NULL, wish_title TEXT NOT NULL, child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE, points_cost INTEGER NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, completed_note TEXT);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, submission_id TEXT REFERENCES task_submissions(id) ON DELETE CASCADE, redemption_id TEXT REFERENCES redemptions(id) ON DELETE CASCADE, original_name TEXT NOT NULL, storage_name TEXT NOT NULL UNIQUE, media_type TEXT NOT NULL CHECK(media_type IN ('image','video')), mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL, CHECK((submission_id IS NULL) <> (redemption_id IS NULL)));
CREATE TABLE IF NOT EXISTS point_ledger(id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE, amount INTEGER NOT NULL, entry_type TEXT NOT NULL CHECK(entry_type IN ('earned','spent')), reference_type TEXT NOT NULL, reference_id TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(family_id,reference_type,reference_id));
CREATE TABLE IF NOT EXISTS idempotency_keys(family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, actor_id TEXT NOT NULL, operation TEXT NOT NULL, key TEXT NOT NULL, status_code INTEGER NOT NULL, response_body TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(family_id,actor_id,operation,key));
CREATE INDEX IF NOT EXISTS idx_instances_family_child ON task_instances(family_id,child_id,due_date);
CREATE INDEX IF NOT EXISTS idx_submissions_task ON task_submissions(family_id,task_instance_id,submitted_at);
CREATE INDEX IF NOT EXISTS idx_ledger_child ON point_ledger(family_id,child_id,created_at);
CREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_idempotency_created ON idempotency_keys(created_at);
CREATE INDEX IF NOT EXISTS idx_attachments_redemption ON attachments(family_id,redemption_id);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
